sys_script_include.script:
var MSSCustodyswifttext = Class.create();
MSSCustodyswifttext.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    //MSSCUSTODY-2986 - new banner text
    responsecode: function(data) {

        var jsonresponse = JSON.parse(data);
        var count = jsonresponse.count;
        return count;
    },
    newbannertext: function() {
        var tradeSysId = this.getTradeReference(this.getParameter('sysparm_trade_id'));
        var status = false;
        var bannertext = new GlideRecord('x_hsb11_mss_c_swft_mss_custody_swift_ondemand_staging');
        bannertext.addQuery('trade_reference', tradeSysId);
        bannertext.query();
        if (bannertext.next()) {
            var count = this.responsecode(bannertext.response_body);
            if (bannertext.getDisplayValue('response_code') == '200' && count == '0')
                status = true;
        }
        return status;
    },
    apibannertext: function() {
        var status = false;
        var bannertext = new GlideRecord('x_hsb11_mss_c_swft_mss_custody_swift_ondemand_staging');
        bannertext.addQuery('trade_reference', this.getParameter('sysparm_trade_id'));
        bannertext.query();
        if (bannertext.next()) {
            var count = this.responsecode(bannertext.response_body);
            if (bannertext.getDisplayValue('response_code') == '200' && count == '0')
                status = true;
        }
        return status;
    },
    getTradeReference: function(number) {
        var tradeNumber = null;
        var qr = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
        qr.addQuery('trade_id', number);
        qr.query();
        if (qr.next()) {
            tradeNumber = qr.getUniqueValue();
        }
        return tradeNumber;
    },
    type: 'MSSCustodyswifttext'
});
